import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"損","description":"高岛易断 - 損","frontmatter":{"title":"損","description":"高岛易断 - 損"},"headers":[],"relativePath":"zh/classics/takashima/041.md","filePath":"zh/classics/takashima/041.md"}'),i={name:"zh/classics/takashima/041.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="損" tabindex="-1">損 <a class="header-anchor" href="#損" aria-label="Permalink to “損”">​</a></h1><h2 id="損-1" tabindex="-1">損 <a class="header-anchor" href="#損-1" aria-label="Permalink to “損”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>损：有孚，元吉，无咎，可贞。利有攸往，曷之用，二簋可用享。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“损”通咸，有心为感，无心为咸。咸，感孚也，故曰“有孚”，以其所损者，出于中心之诚，有足以见信于人也。不然，《损》主节俭，而俭不中礼，卒来讥刺，咎且难免，奚见“元吉”乎？惟损而“有孚”，斯人感其诚，自得“元吉”，复何咎？而可正，以斯而往，无往不利也。《损》俭如此，何用丰为乎？约之“二簋”，亦可“用享”，不特有孚于人，且可上孚夫神明矣。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山下有泽，损。君子以惩忿窒欲。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>地以益而成山，即以损而成泽。山泽本损益之物，不益则山必崩，不损则泽必涸，此卦之所以名《损》也。在人之易发而难制者，无如忿，易炽而难绝者，无如欲。君子见此象，知怒气之盛，势足拔山，故必惩之，以遏刚强之性；贪念之深，盈难填壑，故必窒之，以塞利窦之源。怒起于刚，“惩忿”以息其既往；贪牵于情，“窒欲”以闲其将来。《艮》山止而《兑》泽塞，皆有《损》之象焉。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下行运不正，宜自惩忿。</p><p>○　问营商：营商原在谋财，宜和气，不宜恃气，宜审利，不宜放利。</p><p>○　问功名：忿欲不除，虽有功名，恐不能保其终也。</p><p>○　问战征：“山下有泽”，防山下深处，有敌兵埋伏。</p><p>○　问婚姻：卦自《咸》《恒》来，女悦而男止，夫妇之道，得其正也。</p><p>○　问家宅：此宅后有高山，前有深泽，地势颇险，宜开凿之使平。</p><p>○　问讼事：不使气，不贪财，讼自平矣。</p><p>○　问失物：不得。</p><p>○　问六甲：单月生男，双月生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初爻处卦之始，即为谋事之始也。“已事”者，已其事也，即《艮》止之意；“遄往”者，遄，速也。事既可已，即当“遄往”，一经因循，必致误事，是以有咎，故曰“已事遄往，无咎”。若事在可已不可已之间，已之则失业，不已则害公，惟当酌其轻重缓急之宜，故曰“酌损之”。《象传》以“尚合志”释之，“尚”作上，庶几也，“已事遄往”，庶几与上合志也。虞氏以“已”作祀，谓祭祀，祀事而云“酌损”，即《彖》所云“二簋可用享”之义。其说亦通。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：已往莫追，目下宜急加勉，自可免咎。</p><p>○　问战征：宜速进兵，不可迟缓，辎重粮食，亦须“酌损”。</p><p>○　问营商：贩运宜速，审时度势，宜酌量前行，定可获利，必无咎也。</p><p>○　问功名：速往则得，迟缓无成。</p><p>○　问婚姻：即日迎娶，两姓好合。</p><p>○　问家宅：须速他迁，吉。</p><p>○　问讼事：即速了结罢讼。</p><p>○　问失物：速寻可得。</p><p>○　问六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某来曰：有朋友以急需借金，请占后日利害。筮得《损》之《蒙》。</p><p>断曰：爻居内卦，又在初位，内卦为《兑》，《兑》为口，有开口求人之象。爻辞曰“已事遄往，无咎”，谓当此时处困难，宜抛弃其事，赶急前往，以求救援，得季布之千金一诺，斯可无咎矣。“酌损之”者，谓其所借金数，或有不足，又宜酌量多寡，以赈其乏。玩此爻辞，知需用急切，有不可片刻宽缓者，缓即有咎；但所借之款，必有减少，亦不至空手而回也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二处内卦之中，凡事之有待损之益之者，必其未协于中也，二得中，则以“弗损”为“利贞”。若不可损而损之，则损之反失中，是以“征凶”。《损》与《益》相对，人只知损其所《损》，以损为益，不知不损其所不损，不损乃为《益》。盖其所弗损弗益者，惟在守其中道而已，得其中，即“利贞”也。《象传》以“中以为志”释之，志，犹射之的，以中为的，志之于此也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：好运方来，不减不加，万事得中，自然获利。</p><p>○　问战征：不必减粮，不必添兵，坚守中营，有胜无败；若鲁莽前往，恐有凶也。</p><p>○　问营商：货物合宜，不必减价，无不获利。</p><p>○　问功名：无荣无辱，青毡守旧。</p><p>○　问婚姻：两姓门户相当，吉。</p><p>○　问家宅：地位得中，不必添改，大利。</p><p>○　问讼事：平和。</p><p>○　问失物：原物无失。</p><p>○　问六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某来曰：余为家兄在大阪垄断米市，大受亏耗，有献斡旋之策者，以电报来告，催余运送多金，犹得转败为胜。余恐再失，则受亏愈大，因占其成否如何？筮得《损》之《颐》。</p><p>断曰：卦象泽低而山高，知一时米价，大有高下之势。初次见价低，而多数约买，今临期腾贵，不能不如数应付，以致受耗。东京支店之金，不可动也，谓之“利贞”，若送金而往，谓之“征凶”。大阪本店虽亏，以东京支店维持之，自可挽回，谓之“弗损益之”。后果如所占。</p><p>明治六年，贵显某任某县县令，来请占气运，筮得《损》之《颐》。</p><p>断曰：《损》卦为损下而益上，二爻曰“弗损益之”，是明明言下不必损，上不必益也。今足下出任某县令，占得此爻，爻辞曰：“九二：利贞，征凶。弗损益之。”以九二爻位得正，宜固守成规，不必改作，自得其利。若妄自更张，竞求进步，反致凶也，故无取于《损》，“弗损”即为“利贞”。足下其谨遵爻辞，行之可也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>六三辰在亥，得乾气，《乾》为人，又为行，三爻为三人，故曰“三人行”。《乾》上至三而变《兑》，是三损一也；上互《坤》，变《坤》之上画成《艮》，二阴一阳，故曰“一人行”。三为《损》卦主爻，居《兑》卦之终，《兑》为友，故曰“得其友”，是《艮》得其友也。盖天下事，一则不足，三则过之，以二为得中，乃奇偶之定数，是以“三人行”，则损其一以成二，一人行，则“得其友”亦成二。一而二，二而一，斯之为合志，不然，三人成众，众则人心不一，而疑惑生焉，故《象传》以“三则疑也”释之。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：财运平平，少则获利，多则有损。利双月，不利单月。</p><p>○　问战征：宜从兑方，一路进军，自有援兵相助，有胜无败。</p><p>○　问营商：商业宜于一人独做，否则二人同办，再多则必有损。</p><p>○　问功名：须一人独往，必得成名。</p><p>○　问婚姻：得友，即得偶也，吉。</p><p>○　问家宅：宅在兑方，宅中丁口，每家只有两丁可断。</p><p>○　问讼事：两造成讼，为中有一人唆弄所致，去此一人，则讼了矣。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治二十五年四月，余任北海道炭矿铁道会社长之役，将赴所在，占改正处分如何，筮得《损》之《大畜》。</p><p>断曰：卦体《艮》山《兑》泽，卦德损下益上，明见上卦之山愈高，下卦之泽愈低，有上下不通之势。上下不通，必致事务阻碍，弊端百出，会社因之招损失也。今余恭任社长，势不可不淘汰人员，革除敝害，然此社之弊有二：一系社务，不专关营利主义，一系社员，多由官吏而来；不关营利主义，则社用之出纳无准，由官吏而来，则社规之约束难齐，于是耗费多，冗员众，社中诸务，皆有名无实而已。余欲振兴会社，所以不能不锐意改革也。今占得三爻，玩绎爻辞，是明明告我三分中损一之法也。余得此卦，遂单身赴北海道，断行改革，先减役员三分之一，开其端绪，自是而社务遂大得整顿。</p><p>明治二十五年，余为北海道炭矿会社社长，时因石炭之贩路有碍，所采掘石炭，堆聚不售，社员皆为焦心。筮得《损》之《大畜》。</p><p>断曰：据爻辞称“三人行，则损一人，一人行，则得友”，是明示以少则得利，多则有损，为目下之情形也。至四爻，则曰“损其疾，使遄有喜”，是明言去其货之劣者，使往售而有喜也。五爻则曰“或益之十朋之龟，弗克违，元吉”，按古者货贝五朋，是明言必将益价，莫之能违，是以大吉；上爻则曰“弗损益之，利有攸往”，是明言价格上落，可以到处销售，自能获利也。此后出《损》入《益》，《益》《彖》曰“利有攸往，利涉大川”，是明言可以贩运出洋，销行于外国也。《益》六爻，皆有畅销获利之象，由此推之，以一爻为一年，洞悉九年如一日，集社员示以此断。果哉！二十五年，多蓄石炭，二十六年贩路顿开，照此占辞，料知此后社务，必可隆昌也。</p><p>友人某来，请占事业之成否，筮得《损》之《大畜》。</p><p>断曰：此卦山高而上耸，泽低而下陷，山泽不通气，有草木不生，鱼龟不育之象。今占得三爻，爻辞大旨，谓三人则损，一人则得，知合众兴事，必多意见不合，反致损失。足下能独力成事，必得同心之友来助，可以兴业而有为也。</p><p>明治三十二年一月，自由党与政府提携议会，所议渐合政府之意，自由党乃推选三人，请置大臣之位，政府不允，诸新闻多论其可否。某议员来，请占自由党之意向，果否贯彻，筮得《损》之《大畜》。</p><p>断曰：此卦外卦为政府，内卦为党员，党员向政府推举大臣，政府秉《艮》止之性，不允其请，是下悦上止，故名其卦曰《损》。六三阴爻，与上九阳爻相应，故党员之意，得达政府，在政府为今进党员三人，不得不点大臣三人，是政府之所以为难也。或三人中选用二人乎？谓之“三人行，则损一人”；或只用一人乎？谓之“一人行，则得其友”也。他日偶晤板垣伯，谈及此占，相与一笑。后因党内有猜忌者，此事遂止。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>此爻以阴居阴，为外卦之始，与初九相应，初动体《坎》，《坎》为心病，疾所由生。疾曰“其疾”，“其”指初也，得四为之应，内外皆知所当损，而决计损之，则事之《损》犹在后，疾之《损》为在先也。疾《损》而“遄”，“遄”者初，使之遄者，四也。盖有疾则忧，疾《损》则喜，故“无咎”也。《象传》以“亦可喜”释之，谓不必言《损》事，但言《损》疾，而亦可喜，则《损》事之喜，更可知矣。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：目下虽有小灾，得救即疗，可以转忧为喜。</p><p>○　问营商：货宜减办，使之即往贩售，获利可喜。</p><p>○　问战征：未免遭伤，医治可疗，无咎。</p><p>○　问家宅：此宅阴气过盛，宅眷致多疾病，祈祷可疗，无咎。</p><p>○　问功名：一时难望。</p><p>○　问婚姻：四与初相应，初阳四阴，阴阳相合，必成可喜。</p><p>○　问讼事：“疾”者，害也，去其所害，讼自平矣。</p><p>○　问行人：有事他往，一时未归，有喜无咎。</p><p>○　问六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>工部省书记杉实信氏，予旧亲也。明治十五年二月某日晨起得电报，云杉氏罹急疾，余惊而筮之，得《损》之《睽》。</p><p>断曰：观爻辞，已得明示，谓此病颇重，使名医速施治疗，可立愈也；若迁缓过期，虽名医亦将束手，故曰“损其疾，使遄有喜，无咎”。不幸夜来，大雪纷飞，杜绝行道，朝来风雪益狂，余冒雪赴品川，访于氏之病室，医师皆为大雪所阻，延期不到，果即日死去。亦天数也，可叹可悼！</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“十朋之龟”，元龟长一尺二寸，直二千一百六十，为大贝十朋；公龟九寸以上，直五百，为牡贝十朋；侯龟七寸以上，直三百，为公贝十朋；子龟五寸以上，直百，为小贝十朋——见《汉书》。《坤》数十，又偶为朋，故有“十朋”之象。龟者灵物，能前知吉凶，为卜质吉凶之具。此爻柔顺得中，诚孚于下，故人献其诚。“或益之十朋之龟”，“或”者，不知其所从来之辞，意外之益，君子疑焉，故问之于卜筮。理数已定，十朋之元龟，不能违，其吉可知，故曰“十朋之龟，弗克违，元吉”。《象传》以“自上保祐也”释之，“上祐”者，“自天祐之”也。以爻象言，“上”指上爻，谓上能辅祐六五之君也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：运途全盛，可得意外宠遇。</p><p>○　问战征：军事先卜，其兆大吉。</p><p>○　问营商：财运之来，虽辞不去。</p><p>○　问功名：“自天祐之，吉无不利”。</p><p>○　问家宅：家业兴隆，不卜可知。</p><p>○　问婚姻：天作之合，吉。</p><p>○　问疾病：病愈之后，且可得财，吉。</p><p>○　问六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>东京豪商某家甲干某来，曰仆受本店之命，担任大藏省用务，率数百人以从事。近闻明年大藏省将有改革，此事拟废，则仆所管数百人，一时皆失其业，实所不忍。今转谋于某会社，欲授此等人以相当之业，请占其可否？筮得《损》之《中孚》。</p><p>断曰：此爻以阳居五，位得中正，可知足下秉心正直，当久任其事，不必转而他往也。“十”朋之龟”者，谓将来有意外之幸福也。今者大藏省有改革之议，其中或损或益，足下别有担任之务，此数百人，因之得福，亦未可知。就爻位推之，明年当上爻，爻辞曰“弗损益之，无咎，贞吉，利有攸往”，明年无所损益，且贞吉有利，此事务或不复拟废，亦未定也。总之足下与此数百人，皆得无咎且吉，不必怀忧。某大喜，后果如此占。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>此爻居《损》之极，不可复损也，曰“弗损益之”，其辞与二同，其义与二别。上与三应，三处当《损》之位，人或疑《损》三以《益》上，三之《损》实为上之《益》也，故特示之曰“弗损益之”，以明三虽有损，而于上则无所损益焉。无损则事皆平均而“无咎”，理得安详而“贞吉”。“利有攸往”，即《彖传》所称“与时偕行”之义，上为《艮》之极，极则变，故不为止而为往也。上互《坤》，《坤》为臣，《艮》为家，《艮》动而变《坤》，“得臣无家”之象。弗损下以益上，是王者以天下为家，臣下化之，亦皆国而忘家，故曰“得臣无家”。《象传》以“大得志”释之，谓王者以不损益为《益》，潜移默化，不见其迹，志量之所及甚大，故曰“大得志也”。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：目下绝无窒碍，所往皆利，大吉。</p><p>○　问战征：军队不须添减，率此以往，攻克战胜，无往不利，可“大得志也”。</p><p>○　问营商：货价无甚上落，往售皆可获利，大吉。</p><p>○　问功名：目下即可得志。</p><p>○　问家宅：此宅不必改造，自得吉利。</p><p>○　问疾病：当出外求医，无咎。</p><p>○　问行人：在外大吉，一时未必归家。</p><p>○　问六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治九年，长崎商人大浦阿启与神代某来，曰：前自驿递局，借与横滨制铁所，从事船舶修缮费用，后因得不偿失，大被亏损，计将返纳于驿递局，或转让与他人。两者未决，请占其孰可？筮得《损》之《临》。</p><p>断曰：此爻为《损》之极，今后更无所损，不损则必有所益，故其辞曰“弗损益之，无咎，贞吉，利有攸往”也。二友信之，遂决计续承其业，翌年有西南之役，船舶繁多，大得利益云。</p>',115)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
